sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-ct {
  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 20px 22px;
  margin-top: 24px;
}
.wrm-ct-text { flex: 1; min-width: 240px; }
.wrm-ct-text h3 { margin: 0 0 4px; font-size: 17px; color: var(--ink); }
.wrm-ct-text p  { margin: 0; font-size: 13px; color: var(--ink-2); }

.wrm-ct-btn {
  font-size: 13px; font-weight: 500;
  background: var(--clay); color: var(--on-clay);
  padding: 10px 22px; border-radius: var(--r-pill);
  text-decoration: none; white-space: nowrap;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}
.wrm-ct-btn:hover { background: var(--clay-press); color: var(--on-clay); text-decoration: none; }
